import {effectiveState,strategyOn} from './scenario.js';
/** German residential letting planner. 2026 tariff; projections freeze parameters. */
export const RULES={year:2026,rvCap:101400,healthCap:69750,employeeAllowance:1230,specialAllowance:36,childAllowance:9756,kindergeld:3108,rurupCap:30826};
const n=v=>Number(v)||0;
const sum=a=>a.reduce((s,v)=>s+n(v),0);
const ym=s=>{const [y,m]=String(s).split('-').map(Number);return y*12+m-1;};
const money=v=>Math.round((v+Number.EPSILON)*100)/100;
function rawTariff(x){x=Math.max(0,x);if(x<=12348)return 0;if(x<=17799){let y=(x-12348)/10000;return(914.51*y+1400)*y;}if(x<=69878){let z=(x-17799)/10000;return(173.10*z+2397)*z+1034.87;}return x<=277825?.42*x-11135.63:.45*x-19470.38;}
export const tariff=x=>Math.floor(rawTariff(Math.floor(Math.max(0,n(x)))));
export const incomeTax=(x,joint=false)=>(joint?2:1)*tariff(n(x)/(joint?2:1));
export function loanYear(l,year){let balance=n(l.amount),interest=0,principal=0,payment=0;const start=ym(l.start),end=year*12+11,first=year*12;const monthly=l.monthlyPayment==null?n(l.amount)*(n(l.interest)+n(l.repayment))/1200:n(l.monthlyPayment);const rate=n(l.interest)/1200;if(l.firstInterest!=null&&n(l.firstInterest)>monthly)throw new Error('First-period interest exceeds the instalment; unpaid-interest capitalization is unsupported');
 if(end<start)return {interest:0,principal:0,payment:0,balance:0};
 for(let m=start;m<=end;m++){if(m-start>2400)throw new Error('Loan date exceeds supported horizon');if(balance<=0)break;const accrued=m===start&&l.firstInterest!=null?n(l.firstInterest):balance*rate;const i=l.roundMonthly?money(accrued):accrued;const regular=Math.min(balance+i,monthly);const p=Math.max(0,regular-i);balance=Math.max(0,balance-p);const extra=m%12===11?Math.min(balance,n(l.extra)):0;balance-=extra;if(m>=first){interest+=i;principal+=p+extra;payment+=regular+extra;}}
 return {interest:money(interest),principal:money(principal),payment:money(payment),balance:money(balance)};
}
export function propertyYear(p,year){const share=n(p.ownership)/100,start=ym(p.start),base=year*12;let rent=0,services=0,costs=0,deductibleCosts=0;const costDetails=[];
 for(let m=0;m<12;m++){const date=base+m;if(date>=start){const steps=Math.floor((date-start)/(12*Math.max(1,n(p.rentEvery))));const growth=(1+n(p.rentGrowth)/100)**steps;rent+=(n(p.rent)*growth+n(p.parking))*(1-n(p.vacancy)/100);services+=n(p.serviceIncome)*(1-n(p.vacancy)/100);}}
 for(const c of p.costs){if(c.enabled===false)continue;let a=0;const from=ym(c.from),to=c.to?ym(c.to):9999*12;for(let m=0;m<12;m++){const date=base+m;if(date<from||date>to)continue;if(c.frequency==='once'&&date!==from)continue;if(c.frequency==='annual'&&date%12!==from%12)continue;a+=n(c.amount)*(1+n(c.growth)/100)**Math.floor((date-from)/12);}costs+=a;if(c.type==='deductible')deductibleCosts+=a;costDetails.push({name:c.name,type:c.type,amount:money(a*share)});}
 const basis=p.afaBasis==null?(n(p.purchasePrice)+n(p.buyerCosts))*n(p.buildingShare)/100:n(p.afaBasis);const elapsed=Math.max(0,base-start);const months=Math.max(0,Math.min(12,base+12-Math.max(base,start)));const remaining=Math.max(0,basis-basis*n(p.afaRate)/1200*elapsed);let afa=Math.min(remaining,basis*n(p.afaRate)/1200*months);
 const loans=p.loans.map(l=>({id:l.id,name:l.name,...loanYear(l,year)}));let interest=sum(loans.map(l=>l.interest))*share,principal=sum(loans.map(l=>l.principal))*share;
 rent*=share;services*=share;costs*=share;deductibleCosts*=share;afa*=share;let income=rent+services;
 const actual=p.actuals?.[year];if(actual){if(actual.income!=null)income=n(actual.income);if(actual.interest!=null)interest=n(actual.interest);if(actual.principal!=null)principal=n(actual.principal);if(actual.afa!=null)afa=n(actual.afa);if(actual.deductibleCosts!=null)deductibleCosts=n(actual.deductibleCosts);if(actual.cashCosts!=null)costs=n(actual.cashCosts);}
 const warnings=[];if(n(p.afaRate)>3)warnings.push('Custom AfA above standard rates: supporting remaining-useful-life evidence required.');if(!p.afaEvidence)warnings.push('Building allocation / AfA evidence has not been recorded.');if(p.costs.some(c=>c.type==='capital'))warnings.push('Capital expenditure is cash-only here. Enter an adviser-confirmed revised AfA basis; no automatic capitalization.');if(p.costs.some(c=>c.type==='deductible'&&/repair|renovat|instand|maintenance/i.test(c.name)))warnings.push('Check repairs against the 15% acquisition-related construction-cost rule in the first three years.');for(const l of p.loans)if(year>=Math.floor(ym(l.start)/12)+n(l.fixedYears))warnings.push(`${l.name}: interest fixation ends; unchanged rate assumed thereafter.`);
 const vals={rent,services,income,interest,principal,afa,costs,deductibleCosts,debtService:interest+principal,balance:sum(loans.map(l=>l.balance))*share,result:income-interest-deductibleCosts-afa,cash:income-interest-principal-costs};for(const k of Object.keys(vals))vals[k]=money(vals[k]);return {...vals,loans,costDetails,warnings,actual:!!actual,note:actual?.note||'',basis:money(basis*share)};
}
export function depotSupport(contribution,children,year,eligible){if(year<2027||!eligible)return {allowance:0,deduction:0};const c=Math.max(0,n(contribution)),supported=Math.min(1800,c);const allowance=Math.min(360,supported)*.5+Math.max(0,supported-360)*.25+Math.min(300,supported)*n(children);return {allowance,deduction:supported+allowance};}
export function social(gross,h){gross=Math.max(0,n(gross));const rv=Math.min(gross,RULES.rvCap)*.093,unemployment=Math.min(gross,RULES.rvCap)*.013,health=Math.min(gross,RULES.healthCap)*(.073+n(h.healthExtra)/200);const parent=h.parent||n(h.children)>0;const careRate=(h.saxony?.023:.018)+(parent?0:.006)-Math.min(4,Math.max(0,n(h.childrenUnder25)-1))*.0025;const care=Math.min(gross,RULES.healthCap)*Math.max(0,careRate);return {rv,unemployment,health,care,total:rv+unemployment+health+care,deductible:rv+health*.96+care};}
function taxCore(taxable,h){const joint=!!h.joint,k=Math.max(0,n(h.children)),kg=RULES.kindergeld*k,allowance=RULES.childAllowance*k;const progression=Math.max(0,n(h.progression));const calc=x=>{x=Math.max(0,x);return progression>0&&x>0?Math.floor(incomeTax(x+progression,joint)/(x+progression)*x):incomeTax(x,joint);};const plain=calc(taxable),withChild=calc(taxable-allowance);const childFavorable=plain-withChild>kg;const est=childFavorable?withChild+kg:plain;const soliBasis=withChild;const threshold=joint?40700:20350;const soli=Math.max(0,Math.min(soliBasis*.055,(soliBasis-threshold)*.119));const church=withChild*n(h.churchRate)/100;return {est,soli,church,tax:est+soli+church,childFavorable,kindergeld:kg};}
export function household(h,year,rental=0,options={}){const factor=(1+n(h.salaryGrowth)/100)**Math.max(0,year-n(h.baseYear||2026));const gross=n(h.gross)*factor,spouseGross=h.joint?n(h.spouseGross)*factor:0;const a=social(gross,h),b=social(spouseGross,h);const totalSocial=h.socialOverride==null?a.total+b.total:n(h.socialOverride);const deductibleSocial=h.deductibleOverride==null?a.deductible+b.deductible:n(h.deductibleOverride);const earnerAllowance=Math.min(gross,1230)+Math.min(spouseGross,1230);const count=h.joint?2:1;const requestedRurup=(n(h.rurupMonthly)+(h.joint?n(h.spouseRurupMonthly):0))*12;const rurup=options.pensions===false?0:Math.min(requestedRurup,Math.max(0,30826*count-2*(a.rv+b.rv)));const other=Math.max(36*count,n(h.otherDeductions));const baseTaxable=gross+spouseGross-earnerAllowance-deductibleSocial-other;
 const preDepot=Math.max(0,baseTaxable-rurup+n(rental));const depots=[depotSupport(n(h.depotMonthly)*12,h.depotChildren,year,h.depotEligible),...(h.joint?[depotSupport(n(h.spouseDepotMonthly)*12,h.spouseDepotChildren,year,h.spouseDepotEligible)]:[])];const allowance=options.pensions===false?0:sum(depots.map(d=>d.allowance));const depotDeduction=options.pensions===false?0:sum(depots.map(d=>d.deduction));const before=taxCore(preDepot,h),withDepot=taxCore(Math.max(0,preDepot-depotDeduction),h);const depotFavorable=before.est-withDepot.est>allowance;const taxable=depotFavorable?Math.max(0,preDepot-depotDeduction):preDepot;const selected=depotFavorable?withDepot:before;const est=selected.est+(depotFavorable?allowance:0);const tax=money(est+selected.soli+selected.church);const privateCost=(n(h.privateMonthly)+(h.joint?n(h.spousePrivateMonthly):0))*12;const depotCost=(n(h.depotMonthly)+(h.joint?n(h.spouseDepotMonthly):0))*12;const pensionCost=options.pensions===false?0:privateCost+requestedRurup+depotCost;
 const d=100,joint=h.joint?2:1;const marginalBase=Math.max(0,taxable-(selected.childFavorable?RULES.childAllowance*n(h.children):0));const smooth=x=>rawTariff(Math.max(0,x)/joint)*joint;const rate=n(h.progression)>0?(taxCore(taxable+d,h).est-taxCore(taxable,h).est)/d:(smooth(marginalBase+d)-smooth(marginalBase))/d;
 return {gross:gross+spouseGross,social:money(totalSocial),deductibleSocial:money(deductibleSocial),baseTaxable:money(baseTaxable),taxable:money(taxable),unclamped:baseTaxable-rurup+n(rental)-(depotFavorable?depotDeduction:0),tax,est:money(est),soli:money(selected.soli),church:money(selected.church),marginal:Math.max(0,rate)*100,effective:gross+spouseGross?tax/(gross+spouseGross)*100:0,kindergeld:selected.kindergeld,childFavorable:selected.childFavorable,rurup:money(rurup),pensionCost,allowance:money(allowance),depotDeduction:depotFavorable?depotDeduction:0,depotFavorable,depotExtraTaxBenefit:money(Math.max(0,before.tax-tax)),available:money(gross+spouseGross-totalSocial-tax+selected.kindergeld+n(h.progression)-pensionCost),refund:money(n(h.withheld)+(h.joint?n(h.spouseWithheld):0)-tax)};
}
export function analyze(s,year){s=effectiveState(s);const h={...s.household,baseYear:s.baseYear},baseline=household(h,year,0,{pensions:false}),pensions=household(h,year,0);const partial={...h,rurupMonthly:0,spouseRurupMonthly:0,depotMonthly:0,spouseDepotMonthly:0};let prior=baseline;const pensionStages=[];for(const [key,label] of [['rurupMonthly','Your certified Rürup'],['spouseRurupMonthly','Spouse certified Rürup'],['depotMonthly','Your Altersvorsorgedepot'],['spouseDepotMonthly','Spouse Altersvorsorgedepot']]){partial[key]=h[key];const current=household(partial,year,0);if(strategyOn(s,key))pensionStages.push({key,label,tax:current.tax,taxable:current.taxable,marginal:current.marginal,saving:money(prior.tax-current.tax),monthly:n(h[key]),allowance:current.allowance});prior=current;}let cumulative=0,previous=pensions;const stages=[];for(const p of s.properties){const result=propertyYear(p,year);cumulative+=result.result;const current=household(h,year,cumulative);stages.push({id:p.id,name:p.name,...result,taxable:current.taxable,tax:current.tax,marginal:current.marginal,saving:money(previous.tax-current.tax),afterTaxCash:money(result.cash+previous.tax-current.tax)});previous=current;}
 return {year,baseline,pensions,pensionStages,stages,final:previous,totalResult:money(cumulative),totalBenefit:money(pensions.tax-previous.tax),cash:money(sum(stages.map(p=>p.cash))),afterTaxCash:money(sum(stages.map(p=>p.cash))+pensions.tax-previous.tax),balance:money(sum(stages.map(p=>p.balance))),principal:money(sum(stages.map(p=>p.principal))),householdAvailable:money(previous.available+sum(stages.map(p=>p.cash))),warnings:stages.flatMap(p=>p.warnings.map(w=>`${p.name}: ${w}`))};
}
export function validateState(s){const fail=m=>{throw new Error(m);};if(!s||s.version!==1||!Number.isInteger(s.baseYear)||s.baseYear<2026||s.baseYear>2100||!Array.isArray(s.properties)||s.properties.length>100||!s.household)fail('Invalid or unsupported scenario file.');const check=(v,min,max,label)=>{if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max)fail(`Invalid ${label}`);};const date=(v,label)=>{if(typeof v!=='string'||!/^\d{4}-(0[1-9]|1[0-2])$/.test(v)||Number(v.slice(0,4))<1950||Number(v.slice(0,4))>2150)fail(`Invalid ${label}`);};const ids=new Set();const id=v=>{if(typeof v!=='string'||!v||ids.has(v))fail('Missing or duplicate identifier');ids.add(v);};const text=v=>{if(typeof v!=='string'||v.length>2000)fail('Invalid text field');};
 const plain=v=>v!==null&&typeof v==='object'&&!Array.isArray(v)&&Object.getPrototypeOf(v)===Object.prototype;
 if(!plain(s.household))fail('Invalid household object');
 for(const k of ['joint','parent','saxony','depotEligible','spouseDepotEligible'])if(typeof s.household[k]!=='boolean')fail(`Invalid boolean ${k}`);
 if(!['III/V','IV/IV','IV factor','I','II'].includes(s.household.taxClass))fail('Invalid tax class');
 for(const k of ['gross','spouseGross','children','childrenUnder25','healthExtra','churchRate','otherDeductions','progression','privateMonthly','spousePrivateMonthly','rurupMonthly','spouseRurupMonthly','depotMonthly','spouseDepotMonthly','depotChildren','spouseDepotChildren','withheld','spouseWithheld','salaryGrowth'])check(s.household[k],0,1e9,k);
 for(const k of ['socialOverride','deductibleOverride'])if(s.household[k]!==null)check(s.household[k],0,1e9,k);
 for(const k of ['children','childrenUnder25','depotChildren','spouseDepotChildren'])if(!Number.isInteger(s.household[k])||s.household[k]>20)fail('Invalid child count');
 if(s.household.childrenUnder25>s.household.children||s.household.depotChildren+s.household.spouseDepotChildren>s.household.children)fail('Child allowances allocated more than once / invalid child count');
 if(s.household.salaryGrowth>100)fail('Invalid salary growth');
 for(const [k,v] of Object.entries(s.household)){if(typeof v==='number')check(v,0,1e9,k);else if(v!==null&&typeof v!=='boolean'&&typeof v!=='string')fail(`Invalid household field ${k}`);}
 for(const k of ['gross','spouseGross','children','healthExtra','churchRate','depotMonthly','spouseDepotMonthly','rurupMonthly','spouseRurupMonthly','privateMonthly','spousePrivateMonthly'])check(s.household[k],0,1e9,k);if(s.household.children>20||!Number.isInteger(s.household.children)||s.household.churchRate>10||s.household.healthExtra>10)fail('Invalid household rates or child count');
 for(const p of s.properties){if(!plain(p))fail('Invalid property object');id(p.id);text(p.name);if(p.location!=null)text(p.location);text(p.afaEvidence);if(p.equity!=null)check(p.equity,0,1e10,'equity');date(p.start,'property start');for(const k of ['purchasePrice','buyerCosts','rent','parking','serviceIncome'])check(p[k],0,1e10,k);for(const k of ['buildingShare','ownership','vacancy','afaRate','rentGrowth'])check(p[k],0,100,k);check(p.rentEvery,1,100,'rent interval');if(p.afaBasis!=null)check(p.afaBasis,0,1e10,'AfA basis');if(!Array.isArray(p.loans)||!Array.isArray(p.costs)||!plain(p.actuals))fail('Missing profile ledger');if(p.loans.length>100||p.costs.length>500)fail('Too many ledger entries');
 for(const l of p.loans){id(l.id);text(l.name);date(l.start,'loan start');if(l.fixedUntil){date(l.fixedUntil,'interest fixation end');if(ym(l.fixedUntil)<ym(l.start))fail('Fixation end precedes loan start');}for(const k of ['amount','extra'])check(l[k],0,1e10,k);for(const k of ['interest','repayment'])check(l[k],0,100,k);check(l.fixedYears,1,100,'interest fixation');if(l.monthlyPayment!=null){check(l.monthlyPayment,.01,1e10,'monthly payment');if(l.monthlyPayment<l.amount*l.interest/1200)fail('Monthly payment is below initial interest');}if(l.firstInterest!=null){check(l.firstInterest,0,1e10,'first interest');const installment=l.monthlyPayment??l.amount*(l.interest+l.repayment)/1200;if(l.firstInterest>installment)fail('First-period interest exceeds the instalment');}if(l.roundMonthly!=null&&typeof l.roundMonthly!=='boolean')fail('Invalid monthly rounding flag');}
 for(const c of p.costs){id(c.id);text(c.name);date(c.from,'cost start');if(c.to)date(c.to,'cost end');if(c.to&&ym(c.to)<ym(c.from))fail('Cost end precedes start');check(c.amount,0,1e10,'cost amount');check(c.growth,0,100,'cost inflation');if(!['deductible','reserve','capital','private'].includes(c.type)||!['monthly','annual','once'].includes(c.frequency))fail('Invalid cost category');}
 for(const [y,a] of Object.entries(p.actuals)){if(!/^\d{4}$/.test(y)||!plain(a))fail('Invalid actual-year record');for(const k of ['income','interest','principal','afa','deductibleCosts','cashCosts'])if(a[k]!=null)check(a[k],0,1e10,k);if(a.note!=null)text(a.note);}}
 if(s.strategies!=null){if(!plain(s.strategies))fail('Invalid strategy switches');for(const [k,v]of Object.entries(s.strategies))if(!['rurupMonthly','spouseRurupMonthly','depotMonthly','spouseDepotMonthly','privateMonthly','spousePrivateMonthly','otherDeductions','payrollAllowance'].includes(k)||typeof v!=='boolean')fail('Invalid strategy flag');}
 if(s.risk!=null){const r=s.risk;if(!plain(r))fail('Invalid risk inputs');for(const k of ['liquidCash','essentialMonthly','otherAnnualLow','otherAnnualHigh','optionalMonthly','consumerMonthly','vacancyStressPercent','salaryStressPercent','repairStress','rateShockPoints'])if(r[k]!=null)check(r[k],0,1e9,k);for(const k of ['vacancyStressPercent','salaryStressPercent'])if(r[k]!=null&&r[k]>100)fail('Stress percentages must be 0–100');if(r.rateShockPoints!=null&&r.rateShockPoints>25)fail('Invalid interest shock');for(const k of ['cashApproximate','cashAfterCapital'])if(r[k]!=null&&typeof r[k]!=='boolean')fail('Invalid risk confirmation');if(r.consumerEnd)date(r.consumerEnd,'consumer loan end');if(!Number.isInteger(r.startYear)||r.startYear<2026||r.startYear>2100)fail('Invalid risk horizon');if(r.otherAnnualLow!=null&&r.otherAnnualHigh!=null&&r.otherAnnualLow>r.otherAnnualHigh)fail('Annual expense range is reversed');}
 for(const p of s.properties){if(p.rentIncludesParking&&p.parking>0)fail('Parking is already included; enter a separate cold-rent split or set additional parking to zero');if(p.enabled!=null&&typeof p.enabled!=='boolean')fail('Invalid property activation');if(p.confirmations!=null){if(!plain(p.confirmations))fail('Invalid confirmation flags');for(const v of Object.values(p.confirmations))if(typeof v!=='boolean')fail('Invalid property confirmation');}for(const c of p.costs)if(c.enabled!=null&&typeof c.enabled!=='boolean')fail('Invalid cost activation');if(p.guaranteePlan!=null){const g=p.guaranteePlan;if(!plain(g)||typeof g.enabled!=='boolean'||typeof g.confirmed!=='boolean')fail('Invalid guarantee plan');for(const k of ['annualPremium','coveragePercent'])if(g[k]!=null)check(g[k],0,k==='coveragePercent'?100:1e9,k);for(const k of ['startYear','endYear'])if(!Number.isInteger(g[k])||g[k]<2026||g[k]>2150)fail('Invalid guarantee year');if(g.endYear<g.startYear)fail('Guarantee end precedes start');}}
 if(s.payroll!=null){const p=s.payroll;if(!plain(p))fail('Invalid payroll record');date(p.month,'payroll month');if(!['I','III','IV'].includes(p.taxClass))fail('Unsupported payroll class');for(const k of ['grossMonthly','annualAllowance','healthExtra','health','pension','unemployment','care','taxFreeMonthly','netDeductionsMonthly','observedWageTax','observedPayout','observedNet','observedLoanPayment','observedLoanInterest','observedLoanPrincipal'])check(p[k],0,1e9,k);if(p.monthlyAllowance!=null)check(p.monthlyAllowance,0,1e9,'monthly allowance');for(const k of ['childless','saxony','useObservedSocial'])if(typeof p[k]!=='boolean')fail('Invalid payroll flag');if(![0,8,9].includes(p.churchRate)||p.healthExtra>10)fail('Invalid payroll rate');if(p.approvedPropertyId!=null&&typeof p.approvedPropertyId!=='string')fail('Invalid payroll property reference');}
 return true;
}
